mapper.select:
SELECT a.* FROM swm_hazard_source a
AND a.hazard_name LIKE CONCAT('%', #{hazardName}, '%')
AND a.hazard_category = #{hazardCategory}
AND a.location LIKE CONCAT('%', #{location}, '%')
AND ( a.beacon_identifier LIKE CONCAT('%', #{beaconIdentifier}, '%') OR EXISTS ( SELECT 1 FROM swm_beacon_station b WHERE FIND_IN_SET(b.beacon_id, a.beacon_identifier) > 0 AND (b.device_name LIKE CONCAT('%', #{beaconIdentifier}, '%') OR b.beacon_id LIKE CONCAT('%', #{beaconIdentifier}, '%')) AND b.status = '0' ) )
AND ( a.beacon_identifier LIKE CONCAT('%', #{searchTerm}, '%') OR EXISTS ( SELECT 1 FROM swm_beacon_station b WHERE FIND_IN_SET(b.beacon_id, a.beacon_identifier) > 0 AND (b.device_name LIKE CONCAT('%', #{searchTerm}, '%') OR b.beacon_id LIKE CONCAT('%', #{searchTerm}, '%')) AND b.status = '0' ) )
AND a.beacon_tag LIKE CONCAT('%', #{beaconTag}, '%')
AND a.is_patrol_included = #{isPatrolIncluded}
AND a.hazard_status = #{hazardStatus}
AND a.status = #{status}
ORDER BY a.create_date DESC

SELECT COUNT(*)
FROM swm_hazard_source
WHERE hazard_status = #{status}
AND YEAR(registration_time) = #{year}
AND MONTH(registration_time) = #{month}
AND status = '0';

SELECT COUNT(*)
FROM swm_hazard_source
WHERE status = '0'
    AND YEAR(registration_time) = #{year}
    AND MONTH(registration_time) = #{month}

SELECT
hazard_category AS category,
COUNT(*) AS count
FROM swm_hazard_source
WHERE status = '0'

    AND DATE(registration_time) >= #{beginDate}


    AND DATE(registration_time) <= #{endDate}

GROUP BY hazard_category
ORDER BY count DESC
LIMIT #{limit}

SELECT hazard_category AS category, COUNT(*) AS count FROM swm_hazard_source WHERE status = '0'
AND DATE(registration_time) >= #{beginDate}
AND DATE(registration_time) <= #{endDate}
GROUP BY hazard_category ORDER BY count DESC

SELECT COUNT(*)
FROM swm_hazard_source
WHERE registration_time BETWEEN #{beginDate} AND #{endDate}
AND status = '0'

    AND hazard_status IN

        #{status}
